#define PI 3.14159
#define PW 6.0/iResolution.y
#define S(v) smoothstep(PW, 0.0, v)
#define SN(v) step(0.1666, v)
#define R(v0,v1) random(id+vec2(v0,v1))

float random(vec2 p) {
	vec3 a = fract(p.xyx * vec3(123.34, 234.34, 345.65));
	a += dot(a, a + 24.45);
	return fract(a.x * a.y * a.z);
}

vec2 random2(vec2 st){
    st = vec2(dot(st,vec2(127.1,311.7)),
              dot(st,vec2(269.5,183.3)));
    return 2.0*fract(sin(st)*43758.5453123) - 1.0;
}

// Gradient Noise by Inigo Quilez - https://www.shadertoy.com/view/XdXGW8
float noise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    vec2 u = f*f*(3.0-2.0*f);

    return mix(mix(dot(random2(i + vec2(0)  ), f - vec2(0)  ),
                   dot(random2(i + vec2(1)  ), f - vec2(1,0)), u.x),
               mix(dot(random2(i + vec2(0,1)), f - vec2(0,1)),
                   dot(random2(i + vec2(1)  ), f - vec2(1)  ), u.x), u.y);
}

// 2D SDFs by Inigo Quilez - https://iquilezles.org/articles/distfunctions2d/
float sdCircle(vec2 p, vec2 o, float r)
{
    return length(p-o) - r;
}

float sdRoundedBox(in vec2 p, in vec2 b, in vec2 o, in vec4 r)
{
    p -= o;
    r.xy = (p.x>0.0)?r.xy : r.zw;
    r.x  = (p.y>0.0)?r.x  : r.y;
    vec2 q = abs(p)-b+r.x;
    return min(max(q.x,q.y),0.0) + length(max(q,0.0)) - r.x;
}

float sdVesica(vec2 p, vec2 o, float r, float d)
{
    p = abs(p - o);

    float b = sqrt(r*r-d*d);  // can delay this sqrt by rewriting the comparison
    return ((p.y-b)*d > p.x*b) ? length(p-vec2(0,b))*sign(d)
                               : length(p-vec2(-d,0.0))-r;
}

vec2 rotate2D(vec2 uv, float angle) {
    uv =  mat2(cos(angle),-sin(angle),
               sin(angle), cos(angle)) * uv;
    return uv;
}

float getInnerCorner(vec2 uvGrid, vec2 corner, float rad) {
    return S(sdCircle(uvGrid, corner, rad));
}

void getBlob(
    in vec2 uvGrid,
    in int state,
    in float nTile[8],
    inout vec2 dims,
    inout vec2 offset,
    inout bvec4 innerCorners
) {
    if (state >= 15) { // Not isolated

        int group = (state - 16) / 16; // Determine group (0-14)
        dims = vec2(0.9);

        // Configure based on group
        switch(group) {
            case 0: // Solo right
                dims = vec2(0.9, 0.4);
                offset = vec2(0, 0.5);
                break;
            case 1: // Solo left
                dims = vec2(0.9, 0.4);
                offset = vec2(1, 0.5);
                break;
            case 2: // Solo middle horizontal
                dims = vec2(0.9, 0.4);
                break;
            case 3: // Solo top
                dims = vec2(0.4, 0.9);
                offset = vec2(0.5, 0);
                break;
            case 4: // Top right
                offset = vec2(0);
                if (nTile[7] == 0.0) innerCorners[0] = true; // BL
                break;
            case 5: // Top left
                offset = vec2(1,0);
                if (nTile[6] == 0.0) innerCorners[2] = true; // BR
                break;
            case 6: // Top
                dims = vec2(2, 0.9);
                offset = vec2(0.5, 0);
                if (nTile[7] == 0.0) innerCorners[0] = true; // BL
                if (nTile[6] == 0.0) innerCorners[2] = true; // BR
                break;
            case 7: // Solo bottom
                dims = vec2(0.4, 0.9);
                offset = vec2(0.5, 1.0);
                break;
            case 8: // Bottom right
                offset = vec2(0,1);
                if (nTile[5] == 0.0) innerCorners[1] = true; // TL
                break;
            case 9: // Bottom left
                offset = vec2(1);
                if (nTile[4] == 0.0) innerCorners[3] = true; // TR
                break;
            case 10: // Bottom
                dims = vec2(2, 0.9);
                offset = vec2(0.5, 1);
                if (nTile[5] == 0.0) innerCorners[1] = true; // TL
                if (nTile[4] == 0.0) innerCorners[3] = true; // TR
                break;
            case 11: // Solo middle vertical
                dims = vec2(0.4, 0.9);
                break;
            case 12: // Right
                dims = vec2(0.9, 2);
                offset = vec2(0, 0.5);
                if (nTile[7] == 0.0) innerCorners[0] = true; // BL
                if (nTile[5] == 0.0) innerCorners[1] = true; // TL
                break;
            case 13: // Left
                dims = vec2(0.9, 2);
                offset = vec2(1, 0.5);
                if (nTile[6] == 0.0) innerCorners[2] = true; // BR
                if (nTile[4] == 0.0) innerCorners[3] = true; // TR
                break;
            case 14: // Surrounded
                dims = vec2(2);
                if (nTile[7] == 0.0) innerCorners[0] = true; // BL
                if (nTile[5] == 0.0) innerCorners[1] = true; // TL
                if (nTile[6] == 0.0) innerCorners[2] = true; // BR
                if (nTile[4] == 0.0) innerCorners[3] = true; // TR
                break;
        }
    }
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // UV Grid
    vec2 uv = (fragCoord-0.5*iResolution.xy)/iResolution.y;

    // Camera motion
    vec2 camera = vec2(iTime*0.075, iTime*0.125);
    vec2 mouse = (iMouse.xy-iResolution.xy/2.0)*0.001;
    uv += camera + mouse;

    float steps = 4.0;
    vec2 uvGrid = fract(uv*steps);

    // Cell ids
    vec2 id = floor(uv*steps);
    float grid = floor(mod(id.x + id.y, 2.0));
    float randFromId = R(2,3);

    vec3 col = vec3(0);

    // Crosswalks
    vec2 size = vec2(0.04, 0.01);

    vec2 positions[16];
    positions[0] = vec2(0.21, 0.075); positions[1] = vec2(0.21, 0.03);
    positions[2] = vec2(0.79, 0.075); positions[3] = vec2(0.79, 0.03);
    positions[4] = vec2(0.21, 0.925); positions[5] = vec2(0.21, 0.977);
    positions[6] = vec2(0.79, 0.925); positions[7] = vec2(0.79, 0.977);
    positions[8] = vec2(0.075, 0.21); positions[9] = vec2(0.03, 0.21);
    positions[10] = vec2(0.075, 0.79); positions[11] = vec2(0.03, 0.79);
    positions[12] = vec2(0.925, 0.21); positions[13] = vec2(0.977, 0.21);
    positions[14] = vec2(0.925, 0.79); positions[15] = vec2(0.977, 0.79);

    for (int i = 0; i < 2; i++) {
        if (i > 0) size = size.yx;
        for (int j = 0; j < 8; j++) {
            col += (
                S(sdRoundedBox(uvGrid, size, positions[i * 8 + j], vec4(0.005)))
            );
        }
    }

    // Street lines
    size = vec2(0.5, 0.05);

    positions[0] = vec2(-0.495, 0.35);
    positions[1] = vec2(-0.495, 0.5);
    positions[2] = vec2(-0.495, 0.65);
    positions[3] = vec2(1.495, 0.35);
    positions[4] = vec2(1.495, 0.5);
    positions[5] = vec2(1.495, 0.65);
    positions[6] = vec2(0.35, -0.495);
    positions[7] = vec2(0.5, -0.495);
    positions[8] = vec2(0.65, -0.495);
    positions[9] = vec2(0.35, 1.495);
    positions[10] = vec2(0.5, 1.495);
    positions[11] = vec2(0.65, 1.495);

    for (int i = 0; i < 2; i++) {
        if (i > 0) size = size.yx;
        for (int j = 0; j < 6; j++) {
            col += (
                S(sdRoundedBox(uvGrid, size, positions[i * 6 + j], vec4(0.005)))
            );
        }
    }

    // Parks & lakes
    float parkNoiseScale = 0.3;
    float parkNoise = SN(noise(floor(uv * steps) * parkNoiseScale));
    bool pondParkTile = false;

    float lakeNoiseScale = 0.1;
    float lakeNoise = SN(noise(floor(uv * steps) * lakeNoiseScale)) * (1.0 - parkNoise);

    // Tile state
    float nTile[8];
    if (parkNoise > 0.0 || lakeNoise > 0.0) {

        for (int i=0; i<8; i++) {
            vec2 offset = vec2(
                float(min(i/2, 1)) * -sign(float(i%2)-0.5) / steps,
                1.0/steps
            );
            if (i > 0) {
                switch(i/2) {
                    case 0: offset.y = -1.0/steps; break;
                    case 1: offset.y = 0.0; break;
                    case 2: offset.y = 1.0/steps; break;
                    case 3: offset.y = -1.0/steps; break;
                }
            }
            nTile[i] = SN(noise(floor((uv+offset) * steps) * parkNoiseScale));
        }

        if (parkNoise > 0.0) {

            int state = 0;
            for (int i=0; i < 8; i++) {
                if (nTile[i] > 0.0) {
                    state |= (1 << (7 - i));
                }
            }

            vec2 parkDims = vec2(0.4);
            vec2 parkOffset = vec2(0.5);

            bvec4 parkInnerCorners = bvec4(false);

            getBlob(uvGrid, state, nTile, parkDims, parkOffset, parkInnerCorners);

            float parkSidewalksInnerCornersMask = 0.0;
            float parkInnerCornersMask = 0.0;

            for (int i=0; i<4; i++) {
                if (parkInnerCorners[i]) {
                    parkSidewalksInnerCornersMask += getInnerCorner(uvGrid, vec2(i/2, i%2), 0.1-PW);
                    parkInnerCornersMask += getInnerCorner(uvGrid, vec2(i/2, i%2), 0.165-PW);
                }
            }

            float parkSidewalksMask = S(sdRoundedBox(uvGrid, parkDims, parkOffset, vec4(0.05)))
            * parkNoise - parkSidewalksInnerCornersMask;

            col = mix(vec3(0.35), col, 1.0-parkSidewalksMask);

            float parkMask = S(sdRoundedBox(uvGrid, parkDims-0.065, parkOffset, vec4(0.05)))
            * parkNoise - parkInnerCornersMask;

            col = mix(vec3(0, 0.7, 0.3), col, 1.0-parkMask);

            // Ponds 
            float pond = S(sdCircle(uvGrid, vec2(0.5 + (randFromId - 0.5)*0.35, 0.5 + (randFromId - 0.5)*0.35), max(randFromId*0.15, 0.1)));
            if (parkNoise > 0.0 && R(5,8) > 0.9) {
                pondParkTile = true;
                col = mix(vec3(0, 0.3, 0.8), col, 1.0-pond);
            }
        }

        else if (lakeNoise > 0.0) {

            // Lake tile state
            for (int i=0; i<8; i++) {
                vec2 offset = vec2(
                    float(min(i/2, 1)) * -sign(float(i%2)-0.5) / steps,
                    1.0/steps
                );
                if (i > 0) {
                    switch(i/2) {
                        case 0: offset.y = -1.0/steps; break;
                        case 1: offset.y = 0.0; break;
                        case 2: offset.y = 1.0/steps; break;
                        case 3: offset.y = -1.0/steps; break;
                    }
                }
                nTile[i] = (1.0 - nTile[i]) * SN(noise(floor((uv+offset) * steps) * lakeNoiseScale));
            }

            int state = 0;
            for (int i=0; i < 8; i++) {
                if (nTile[i] > 0.0) {
                    state |= (1 << (7 - i));
                }
            }

            vec2 lakeDims = vec2(0.4);
            vec2 lakeOffset = vec2(0.5);

            bvec4 lakeInnerCorners = bvec4(false);

            getBlob(uvGrid, state, nTile, lakeDims, lakeOffset, lakeInnerCorners);

            float lakeSidewalksInnerCornersMask = 0.0;
            float lakeBeachesInnerCornersMask = 0.0;
            float lakeInnerCornersMask = 0.0;
            float lakeWavesInnerCornersMask = 0.0;

            float lakeInnerCornersScale = 0.015*cos(-3.0*iTime) + 0.235 - PW;
            float lakeWavesInnerCornersScale = 0.5-PW;
            float lakeWavesAnim = smoothstep(0.0, 1.0+PW*20.0, cos(-3.0*iTime + 80.0 * sdRoundedBox(uvGrid, lakeDims - 0.15, lakeOffset, vec4(0.25))) + 0.5);
            float lakeWavesFade = clamp(sin(1.1 + 6.0 * sdRoundedBox(uvGrid, lakeDims-0.15, lakeOffset, vec4(0.25))), 0.0, 1.0);

            for (int i=0; i<4; i++) {
                if (lakeInnerCorners[i]) {
                    lakeSidewalksInnerCornersMask += getInnerCorner(uvGrid, vec2(i/2, i%2), 0.1-PW);
                    lakeBeachesInnerCornersMask += getInnerCorner(uvGrid, vec2(i/2, i%2), 0.165-PW);
                    lakeInnerCornersMask += getInnerCorner(uvGrid, vec2(i/2, i%2), lakeInnerCornersScale);

                    float ic = getInnerCorner(uvGrid, vec2(i/2, i%2), lakeWavesInnerCornersScale);
                    lakeWavesInnerCornersMask += ic;
                    lakeWavesAnim = mix((smoothstep(1.0+PW*20.0, 0.0, (cos(3.0*iTime + 80.0 * sdRoundedBox(uvGrid, vec2(1.85), vec2(-1.7575) + vec2(i/2, i%2)*4.515, vec4(0.1))) + 0.5)) - 1.0) * ic, lakeWavesAnim, 1.0-ic);
                    lakeWavesFade = mix(clamp(sin(1.1 + 6.0 * sdRoundedBox(uvGrid, vec2(1.85), vec2(-1.7575) + vec2(i/2, i%2)*4.515, vec4(0.1))), 0.0, 1.0) * ic, lakeWavesFade, 1.0-ic);
                }
            }

            float lakeSidewalksMask = S(sdRoundedBox(uvGrid, lakeDims, lakeOffset, vec4(0.05)))
            * lakeNoise - lakeSidewalksInnerCornersMask;

            col = mix(vec3(0.35), col, 1.0-lakeSidewalksMask);

            float lakeBeachesMask = S(sdRoundedBox(uvGrid, lakeDims-0.065, lakeOffset, vec4(0.05)))
            * lakeNoise - lakeBeachesInnerCornersMask;

            col = mix(vec3(0.9, 0.65, 0.45), col, 1.0-lakeBeachesMask);

            float lakeMask = S(sdRoundedBox(uvGrid, lakeDims - 0.015*cos(-3.0*iTime) - 0.135, lakeOffset, vec4(0.265)))
            * lakeNoise - lakeInnerCornersMask;

            float lakeWavesMask = (1.0 - S(sdRoundedBox(uvGrid, lakeDims-0.35, lakeOffset, vec4(0.2))))
            * lakeNoise - lakeWavesInnerCornersMask;

            vec3 lakeWavesCol = mix(vec3(0, 0.3, 0.7), vec3(0.75, 0.95, 1.0), lakeWavesAnim * lakeWavesFade * lakeWavesMask);

            col = mix(lakeWavesCol, col, 1.0-lakeMask);

            // Boats
            vec2 boatOffset = vec2(0.5 + (R(6,7) - 0.5)*0.35, 0.5 + (R(6.5,7.5) - 0.5)*0.35);
            vec2 boatRotation = rotate2D(uvGrid - boatOffset, 2.0*PI*R(6,7));
            float boatScale = max(randFromId * 0.3, 0.1);

            float boat = S(sdVesica(boatRotation, vec2(0), boatScale, 0.75 * boatScale));
            vec3 randBoatColor = vec3(R(3,1), R(5,4), R(7,1)) * 0.25 + 0.75;
            if (lakeNoise > 0.0 && R(5,8) > 0.85) {
                col = mix(randBoatColor, col, 1.0-boat);
            }

        }

    }

    // Blocks, buildings, vehicles, etc
    else {

        // Bike lanes
        col += S(sdRoundedBox(uvGrid, vec2(0.4), vec2(0.5), vec4(0.05))) * vec3(0, 0.6, 0.2);

        // Sidewalks
        float sidewalks = S(sdRoundedBox(uvGrid, vec2(0.335), vec2(0.5), vec4(0.05)));
        col = mix(vec3(0.35), col, 1.0-sidewalks);

        // Block states
        float blockNoise = clamp(noise(floor(uv * steps) * 0.4) * 6.0 + 0.5, 0.0, 1.0);
        int blockState = 3 - int(blockNoise*3.999);

        // Building colors
        vec3 buildingColors[8];
        buildingColors[0] = vec3(0.8, 0.5, 0.2);
        buildingColors[1] = vec3(0.7, 0.7, 0.8);
        buildingColors[2] = vec3(0.8, 0.4, 0.3);
        buildingColors[3] = vec3(0.7, 0.7, 0.6);
        buildingColors[4] = vec3(0.6, 0.6, 0.6);
        buildingColors[5] = vec3(0.8, 0.7, 0.6);
        buildingColors[6] = vec3(0.1, 0.1, 0.1);
        buildingColors[7] = vec3(0.4, 0.5, 0.6);

        // Building params
        vec2 bColRange = vec2(4);
        vec2 buildingDims = vec2(0.26, 0.12);
        vec2 buildingOffset = vec2(0.365, 0.635);
        vec4 buildingRounding = vec4(0.04);

        // Draw buildings
        for (int i=0; i<blockState+1; i++) {

            vec2 cr = vec2(4);
            vec2 d = vec2(0.26, 0.12);
            vec2 o = vec2(0.365, 0.635);

            switch(blockState) {
                case 0:
                    d = buildingDims.xx;
                    o = vec2(0.5);
                    break;
                case 1:
                    cr = vec2(5,3);
                    o = vec2(0.5, buildingOffset[i]);
                    if (randFromId < 0.5) {
                        d = buildingDims.yx;
                        o = o.yx;
                    }
                    break;
                case 2:
                    cr = vec2(5,1);
                    if (i > 0) d = buildingDims.yy;
                    int config = int(randFromId * 3.99);
                    switch(config) {
                        case 0:
                            if (i > 0) o.x = buildingOffset[i-1];
                            else o = vec2(0.5, buildingOffset.x);
                            break;
                        case 1:
                            if (i > 0) {
                                o.x = buildingOffset[i-1];
                                o.y = buildingOffset.x;
                            }
                            else o = vec2(0.5, buildingOffset.y);
                            break;
                        case 2:
                            if (i > 0) {
                                o.x = buildingOffset.y;
                                o.y = buildingOffset[i-1];
                            }
                            else {
                                d = buildingDims.yx;
                                o = vec2(buildingOffset.x, 0.5);
                            }
                            break;
                        case 3:
                            if (i > 0) o.y = buildingOffset[i-1];
                            else { 
                                d = buildingDims.yx;
                                o = vec2(buildingOffset.y, 0.5);
                            }
                            break;
                    }
                    break;
                case 3:
                    cr = vec2(5,0);
                    d = buildingDims.yy;
                    switch (i) {
                        case 0: o = buildingOffset.xx; break;
                        case 1: o = buildingOffset.xy; break;
                        case 2: o = buildingOffset.yx; break;
                        case 3: o = buildingOffset.yy; break;
                    }
                    break;
            }

            float building = S(sdRoundedBox(uvGrid, d, o, buildingRounding));
            int bColIndex = int(R(i, i+1)*cr.x + cr.y);
            col = mix(buildingColors[bColIndex], col, 1.0-building);
        }

        // Cars, buses
        float carTimeMult = max(randFromId, 0.5);
        float carTimeAdd = random(vec2(randFromId, randFromId+0.33));
        float carX = smoothstep(-0.9, 0.9, sin(iTime*carTimeMult + carTimeAdd)) * 0.9 + 0.05;
        float carY = smoothstep(-0.9, 0.9, cos(iTime*carTimeMult + carTimeAdd)) * 0.9 + 0.05;
        float carDX = carX - (smoothstep(-0.9, 0.9, sin((iTime-0.01)*carTimeMult + carTimeAdd)) * 0.9 + 0.05);
        float carDY = carY - (smoothstep(-0.9, 0.9, cos((iTime-0.01)*carTimeMult + carTimeAdd)) * 0.9 + 0.05);
        vec3 randCarColor = vec3(R(3,1), R(5,4), R(7,1));

        float car = S(
            sdRoundedBox(
                rotate2D(
                    uvGrid-vec2(carX, carY),
                    atan(carDY, carDX)
                ),
                vec2(0.04, 0.03),
                vec2(0),
                vec4(0.01))
            );

        col = mix(randCarColor, col, 1.0-car);

        float busX = smoothstep(-0.9, 0.9, sin(iTime*carTimeMult + carTimeAdd + PI)) * 0.9 + 0.05;
        float busY = smoothstep(-0.9, 0.9, cos(iTime*carTimeMult + carTimeAdd + PI)) * 0.9 + 0.05;
        float busDX = busX - (smoothstep(-0.9, 0.9, sin((iTime-0.01)*carTimeMult + carTimeAdd + PI)) * 0.9 + 0.05);
        float busDY = busY - (smoothstep(-0.9, 0.9, cos((iTime-0.01)*carTimeMult + carTimeAdd + PI)) * 0.9 + 0.05);
        vec3 busColor = vec3(0, 0.5, 1.0);

        float bus = S(
            sdRoundedBox(
                rotate2D(
                    uvGrid-vec2(busX, busY),
                    atan(busDY, busDX)
                ),
                vec2(0.08, 0.035),
                vec2(0),
                vec4(0.01))
            );

        if (randFromId > 0.4) col = mix(busColor, col, 1.0-bus);

        // Pedestrians
        float pedTimeMult = (randFromId*2.0 - 1.0)*0.25;
        if (pedTimeMult > 0.0 && pedTimeMult < 0.1) pedTimeMult = 0.1;
        if (pedTimeMult < 0.0 && pedTimeMult > -0.1) pedTimeMult = -0.1;
        float pedTimeAdd = random(vec2(randFromId, randFromId-0.33));
        float pedX = smoothstep(-0.6, 0.6, 0.65*sin(iTime*pedTimeMult + pedTimeAdd)) * 0.6 + 0.2;
        float pedY = smoothstep(-0.6, 0.6, 0.65*cos(iTime*pedTimeMult + pedTimeAdd)) * 0.6 + 0.2;
        float pedDX = (smoothstep(-0.6, 0.6, 0.65*sin((iTime+1.0)*pedTimeMult + pedTimeAdd)) * 0.6 + 0.2) - pedX;
        float pedDY = (smoothstep(-0.6, 0.6, 0.65*cos((iTime+1.0)*pedTimeMult + pedTimeAdd)) * 0.6 + 0.2) - pedY;
        vec3 randPedColor = vec3(R(4,2), R(8,7), R(5,3));

        float pedestrian = S(
            sdRoundedBox(
                rotate2D(
                    uvGrid-vec2(pedX, pedY),
                    atan(pedDY, pedDX)
                ),
                vec2(0.0075, 0.015),
                vec2(0),
                vec4(0.005))
            );

        col = mix(randPedColor, col, 1.0-pedestrian);

    }

    // Trees
    if (lakeNoise < 1.0) {
        vec2 treeBlockPos = vec2(0.17, 0.83);
        for (int i=0; i<6; i++) {
            float tree;
            vec3 treeCol = vec3(R(i,i+1)*0.5, 0.4, 0.15-randFromId*0.15);
            vec2 treeRand = vec2(
                R(i,i+1)-0.5,
                R(float(i)+0.5, float(i)+1.5)-0.5
            );
            if (i < 4 && parkNoise < 1.0) {
                vec2 treePos;
                switch(i) {
                    case 0: treePos = vec2(treeRand[0]*0.5 + 0.5, treeBlockPos[0]); break;
                    case 1: treePos = vec2(treeRand[0]*0.5 + 0.5, treeBlockPos[1]); break;
                    case 2: treePos = vec2(treeBlockPos[0], treeRand[0]*0.5 + 0.5); break;
                    case 3: treePos = vec2(treeBlockPos[1], treeRand[0]*0.5 + 0.5); break;
                }
                tree = S(sdCircle(uvGrid, treePos, max(treeRand[0] * 0.06, 0.045)));
            }
            else if (parkNoise > 0.0 && !pondParkTile && random(vec2(float(i+10)) + floor(uv)) > 0.25) {
                tree = S(sdCircle(uvGrid, vec2(treeRand[0]*0.6 + 0.5, treeRand[1]*0.6 + 0.5), max(R(i,i+1) * 0.075, clamp(0.01*float(i), 0.05, 0.075))));
            }
            col = mix(treeCol, col, 1.0-tree);
        }
    }

    // Elevated trains
    float trainCarOffset = 1.0/iResolution.y + 0.125;
    float trainRandX = random(vec2(id.x));
    float trainRandY = random(vec2(id.y));
    vec2 trainSizeV = vec2(0.035, 0.06);
    vec2 trainSizeH = vec2(0.06, 0.035);
    vec4 trainRounding = vec4(0.01);

    vec4 trainMask = vec4(
        floor(random(vec2(id.x)) * 1.2),
        floor(random(vec2(id.x+1.0)) * 1.2),
        floor(random(vec2(id.y)) * 1.2),
        floor(random(vec2(id.y+1.0)) * 1.2)
    );

    vec4 trainTrack = vec4(
        S(sdRoundedBox(vec2(uvGrid.x, 0), vec2(0.04, 1), vec2(0.055, 0), vec4(0))),
        S(sdRoundedBox(vec2(uvGrid.x, 0), vec2(0.04, 1), vec2(0.945, 0), vec4(0))),
        S(sdRoundedBox(vec2(0, uvGrid.y), vec2(1, 0.04), vec2(0, 0.055), vec4(0))),
        S(sdRoundedBox(vec2(0, uvGrid.y), vec2(1, 0.04), vec2(0, 0.945), vec4(0)))
    );

    vec4 train = vec4(
        S(sdRoundedBox(vec2(uvGrid.x, uv.y-camera.y + fract(iTime*-0.1*max(trainRandX, 0.5) + trainRandX * 10.0)*10.0 - 5.0), trainSizeV, vec2(0.055, 0), trainRounding)),
        S(sdRoundedBox(vec2(uvGrid.x, uv.y-camera.y + fract(iTime*0.1*max(trainRandX, 0.5) + trainRandX * 10.0)*10.0 - 5.0), trainSizeV, vec2(0.945, 0), trainRounding)),
        S(sdRoundedBox(vec2(uv.x-camera.x + fract(iTime*-0.1*max(trainRandY, 0.5) + trainRandY * 10.0)*10.0 - 5.0, uvGrid.y), trainSizeH, vec2(0, 0.055), trainRounding)),
        S(sdRoundedBox(vec2(uv.x-camera.x + fract(iTime*0.1*max(trainRandY, 0.5) + trainRandY * 10.0)*10.0 - 5.0, uvGrid.y), trainSizeH, vec2(0, 0.945), trainRounding))
    );

    vec4 trainOffsets = vec4(
        fract(iTime * -0.1 * max(trainRandX, 0.5) + trainRandX * 10.0) * 10.0 - 5.0,
        fract(iTime * 0.1 * max(trainRandX, 0.5) + trainRandX * 10.0) * 10.0 - 5.0,
        fract(iTime * -0.1 * max(trainRandY, 0.5) + trainRandY * 10.0) * 10.0 - 5.0,
        fract(iTime * 0.1 * max(trainRandY, 0.5) + trainRandY * 10.0) * 10.0 - 5.0
    );

    vec3 trainCol = vec3(0.7, 0.8, 0.9);
    for (int car=0; car<3; car++) {
        float offset = trainCarOffset * float(car+1);

        vec4 at = vec4(
            S(sdRoundedBox(vec2(uvGrid.x, uv.y - camera.y + trainOffsets[0] + offset), trainSizeV, vec2(0.055, 0), trainRounding)),
            S(sdRoundedBox(vec2(uvGrid.x, uv.y - camera.y + trainOffsets[1] - offset), trainSizeV, vec2(0.945, 0), trainRounding)),
            S(sdRoundedBox(vec2(uv.x - camera.x + trainOffsets[2] + offset, uvGrid.y), trainSizeH, vec2(0, 0.055), trainRounding)),
            S(sdRoundedBox(vec2(uv.x - camera.x + trainOffsets[3] - offset, uvGrid.y), trainSizeH, vec2(0, 0.945), trainRounding))
        );

        for (int i=0; i<4; i++) {
            train[i] = mix(at[i], train[i], 1.0-at[i]);
        }
    }

    for (int i=0; i<4; i++) {
        if (trainMask[i] > 0.0) {
            if (i>1) trainCol = vec3(0.9, 0.8, 0.7);
            col = mix(trainCol - 0.3, col, 1.0-trainTrack[i]);
            col = mix(trainCol, col, 1.0-train[i]);
        }
    }

    // Helicopter
    float helicopter = S(sdCircle(uv - camera, vec2(sin(iTime), cos(iTime*0.5))*2.0, 0.1));
    col = mix(vec3(0.2, 0.4, 0.6), col, 1.0-helicopter);

    // Out color
    col = max(col, 0.05);
    fragColor = vec4(col, 1.0);
}
